class BoyerMooreSearch:
    def __init__(self, text, pattern):
        self._text = text
        self._pattern = pattern
        self._text_len = len(text)
        self._pat_len = len(pattern)

    @property
    def text(self):
        return self._text

    @property
    def pattern(self):
        return self._pattern

    @property
    def text_len(self):
        return self._text_len

    @property
    def pat_len(self):
        return self._pat_len

    def match_in_pattern(self, char):
        for i in range(self._pat_len - 1, -1, -1):
            if char == self._pattern[i]:
                return i
        return -1

    def mismatch_in_text(self, current_pos):
        for i in range(self._pat_len - 1, -1, -1):
            if self._pattern[i] != self._text[current_pos + i]:
                return current_pos + i
        return -1

    def bad_character_heuristic(self):
        positions = []
        i = 0
        while i <= self._text_len - self._pat_len:
            mismatch_index = self._get_mismatch_index(i)
            if mismatch_index == -1:
                positions.append(i)
                i += 1
            else:
                i = self._compute_next_position(mismatch_index)
        return positions

    def _get_mismatch_index(self, current_pos):
        return self.mismatch_in_text(current_pos)

    def _compute_next_position(self, mismatch_index):
        match_index = self._match_char_in_pattern(self._text[mismatch_index])
        shift = mismatch_index - match_index
        return max(shift, 1)

    def _match_char_in_pattern(self, char):
        return self.match_in_pattern(char)
